import { pad } from './pad.js'

export interface FormatOptions {
  locale?: string
  withOffset?: boolean
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

/** Format a date as "2026-09-21 14:05:09". */
export function formatDate(date: Date, options: FormatOptions = {}): string {
  const year = date.getUTCFullYear()
  const month = pad(date.getUTCMonth() + 1)
  const day = pad(date.getUTCDate())
  const hours = pad(date.getUTCHours())
  const minutes = pad(date.getUTCMinutes())
  const seconds = pad(date.getUTCSeconds())
  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`
}

export function formatMonth(date: Date): string {
  return MONTHS[date.getUTCMonth()] ?? 'Unknown'
}

export function formatRange(start: Date, end: Date, options: FormatOptions = {}): string {
  const left = formatDate(start, options)
  const right = formatDate(end, options)
  return left === right ? left : `${left} - ${right}`
}
